mapper.select:
select 
from preg_measurement m
where m.del_flag = '0'

    and m.metric_code = #{metricCode}


    and m.record_date >= #{from}


    and m.record_date <= #{to}


    and m.scene_code = #{scene}


    and m.unit_code = #{unit}


    and m.report_id = #{reportId}

order by m.occurred_at desc, m.id desc

select m.record_date as recordDate, count(1) as total
from preg_measurement m
where m.record_date >= #{from}
  and m.record_date <= #{to}
  and m.del_flag = '0'
group by m.record_date

select 
from preg_measurement m
where m.metric_code = #{metricCode}
  and m.del_flag = '0'

    and m.record_date >= #{from}


    and m.record_date <= #{to}


    and m.scene_code = #{scene}


    and m.unit_code = #{unit}

order by m.occurred_at asc, m.id asc
